// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address and a uint v and the number of recipients (n); we will build an array of addresses
    // The adversarial callee ReverterRecorder can be toggled to either succeed or revert on its transferFrom function.
    function testFuzz_property(address from, uint256 v, uint8 n, bool shouldRevert) public {
        // keep n small but allow 1..10 recipients; require at least one recipient as contract requires _tos.length>0
        uint8 boundedN = uint8(bound(n, 1, 10));

        // deploy the adversarial helper that implements the exact signature transferFrom(address,address,uint256)
        ReverterRecorder helper = new ReverterRecorder();
        helper.setShouldRevert(shouldRevert);

        // build the _tos array: all entries point to helper so each call goes to the same adversarial callee
        address[] memory tos = new address[](boundedN);
        for (uint256 i = 0; i < boundedN; i++) {
            tos[i] = address(helper);
        }

        // Call c.transfer and observe whether it completes or reverts.
        // The reference implementation requires that if the callee reverts, c.transfer reverts too.
        // The mutant removed the require(_s) and thus will return true even when helper reverts.
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assert): For ALL admissible inputs, when the helper is set to revert its transferFrom,
        // the correct contract will cause c.transfer to revert (so ok==false). Therefore we assert that if shouldRevert==true then ok==false.
        // This property holds for the reference C for every input; the mutant (which ignores the call success) will return true (ok==true)
        // for some inputs when shouldRevert==true, causing this assertion to fail on the mutant.
        if (shouldRevert) {
            assertTrue(!ok);
        } else {
            // when helper does not revert, both reference and mutant should complete successfully
            assertTrue(ok);
        }
    }
}

// Adversarial observing/reverting helper. It declares the exact function selector
// called by C: transferFrom(address,address,uint256). It can be toggled to revert or to record calls.
contract ReverterRecorder {
    bool public shouldRevert;
    // simple recording fields (counts) though the test only needs the revert behaviour
    uint256 public calls;
    address public last_from;
    address public last_to;
    uint256 public last_v;

    function setShouldRevert(bool v) external {
        shouldRevert = v;
    }

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        last_from = from;
        last_to = to;
        last_v = v;
        if (shouldRevert) {
            revert("forced revert");
        }
        return true;
    }
}
